SELECT id, employee_no, name, id_card_no, department_id, status, created_at, updated_at
FROM employee
WHERE status = 'ACTIVE'

    AND 1 = 1
    AND department_id = #{departmentId}
    AND id = #{employeeId}
    AND 1 = 0


    AND (employee_no LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}

ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM employee
WHERE status = 'ACTIVE'

    AND 1 = 1
    AND department_id = #{departmentId}
    AND id = #{employeeId}
    AND 1 = 0


    AND (employee_no LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}
